public class Main {
    // 1. 정수 더하기
    public static int add(int a, int b) {
        return a + b;
    }

    // 2. 실수 더하기 (이름이 같아도 OK)
    public static double add(double a, double b) {
        return a + b;
    }

    public static void main(String[] args) {
        System.out.println(add(3, 7));       // 1번 호출
        System.out.println(add(3.5, 4.5));   // 2번 호출
    }
}
